// It's a Wonderful World card database for the card picker. Shared by the
// browser and the tests.
//
// The entries in ./card-data.js are generated by scripts/import-cards.js from
// the community "IAWW Card Overview" spreadsheet; check them against the
// printed cards. Each entry looks like this:
//
//   {
//     name: "…",               // as printed
//     exp: ["base"],           // sets the card needs: base, ks (Kickstarter promo), or EXPANSIONS ids
//     pack: "IHB",             // Leisure & Decadence booster pack, when only in one of them
//     n: 1,                    // copies in the deck
//     type: "structure",       // structure, vehicle, research, project, discovery
//     cost: { material: 3 },   // any of the 5 resources, kry, fin, gen
//     prod: { energy: 1 },     // flat production per round
//     scale: { res, per, n },  // n of res per built card of type per
//     corr: {},                // Corruption & Ascension: corruption per round
//     bonus: { fin: 1 },       // construction bonus: fin, gen, kry
//     recycle: "science",      // recycling bonus resource
//     vp: 2,                   // printed VP
//     combo: { t, x },         // x VP per built card of type t, or per fin / gen
//     duo: { a, b, x },        // Corruption & Ascension: x VP per pair
//     note: "Not counted: …",  // what the card does that the tracker cannot model
//   }
//
// Cards the tracker cannot represent (Memorials, Revolutions) are left out.

import { sanitizeCard } from "./def.js";
import CARD_DATA from "./card-data.js";

export const CARDS = CARD_DATA;

// A database entry as a tracker card, ready for the picker or a log event.
export const toCard = (entry) => sanitizeCard(entry);

// Entries for the sets in this session. Kickstarter promos have no session
// option, so they are always listed.
const inPlay = (game, k) => k === "base" || k === "ks" || !!(game.exp && game.exp[k]);
export const cardsFor = (game) => CARDS.filter((c) => c.exp.every((k) => inPlay(game, k)));

/* ---------- matching a card as it is entered ---------- */
// Like an old satnav: each value entered narrows the list, and values no
// remaining card has can be greyed out. A blank or 0 field means "not entered".
const CUBES = ["material", "energy", "science", "gold", "exploration"];
export const PATHS = [
  "type",
  ...CUBES.concat(["kry", "fin", "gen"]).map((k) => "cost." + k),
  ...CUBES.map((k) => "prod." + k),
  ...CUBES.map((k) => "corr." + k),
  ...["fin", "gen", "kry"].map((k) => "bonus." + k),
  "recycle", "vp", "scale.res", "scale.per", "scale.n", "combo.t", "combo.x", "duo.a", "duo.b", "duo.x",
];
const val = (c, path) => path.split(".").reduce((o, k) => (o == null ? undefined : o[k]), c) || 0;

// Cards in `list` that agree with every field entered in `draft`, ignoring `skip`.
export function matchCards(draft, list, skip = "") {
  const set = PATHS.filter((p) => p !== skip && val(draft, p));
  return list.filter((c) => set.every((p) => val(c, p) === val(draft, p)));
}

// The values `path` can still take, given everything else entered (0 = none).
export const optionsFor = (draft, list, path) => new Set(matchCards(draft, list, path).map((c) => val(c, path)));
